package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block.RectangleConstraint;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeNN.
 * Since arrangeNN is protected, we use a Testable subclass to expose it.
 */
public class BorderArrangement_arrangeNN_TriageGen1Test {

    private TestableBorderArrangement arrangement;
    private BlockContainer container;
    private Graphics2D g2;

    // Subclass to access the protected method
    private static class TestableBorderArrangement extends BorderArrangement {
        public Size2D callArrangeNN(BlockContainer container, Graphics2D g2) {
            return super.arrangeNN(container, g2);
        }

        // Helper to inject blocks for testing since fields are private in original class
        // In JFreeChart, these are usually set via add(Block, Object)
        // We assume the keys are top, bottom, left, right, center based on implementation logic
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        container = mock(BlockContainer.class);
        g2 = mock(Graphics2D.class);
    }

    @Test
    public void testArrangeNN_AllNull() {
        Size2D result = arrangement.callArrangeNN(container, g2);
        assertEquals(0.0, result.width, 1e-9);
        assertEquals(0.0, result.height, 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyTop() {
        Block top = mock(Block.class);
        when(top.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(100, 50));
        arrangement.add(top, "top"); // Assuming key logic matches implementation

        // To ensure we are testing the specific protected fields, 
        // we must realize 'add' in BorderArrangement sets these specific fields.
        // In JFreeChart, keys are BorderArrangement.TOP, etc.

        // Re-injecting via reflection if add() doesn't map correctly, 
        // but following standard JFreeChart API:
        arrangement.add(top, BorderArrangement.TOP);

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(50.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(top).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getX(), 1e-9);
        assertEquals(0.0, captor.getValue().getY(), 1e-9);
        assertEquals(100.0, captor.getValue().getWidth(), 1e-9);
        assertEquals(50.0, captor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyBottom() {
        Block bottom = mock(Block.class);
        when(bottom.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(100, 40));
        arrangement.add(bottom, BorderArrangement.BOTTOM);

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(40.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(bottom).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getY(), 1e-9);
        assertEquals(40.0, captor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyLeft() {
        Block left = mock(Block.class);
        when(left.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(30, 60));
        arrangement.add(left, BorderArrangement.LEFT);

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(30.0, result.width, 1e-9);
        assertEquals(60.0, result.height, 1e-9);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(left).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getX(), 1e-9);
        assertEquals(60.0, captor.getValue().getHeight(), 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyRight() {
        Block right = mock(Block.class);
        when(right.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(20, 70));
        arrangement.add(right, BorderArrangement.RIGHT);

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(20.0, result.width, 1e-9);
        assertEquals(70.0, result.height, 1e-9);
    }

    @Test
    public void testArrangeNN_OnlyCenter() {
        Block center = mock(Block.class);
        when(center.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(50, 50));
        arrangement.add(center, BorderArrangement.CENTER);

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(50.0, result.width, 1e-9);
        assertEquals(50.0, result.height, 1e-9);
    }

    @Test
    public void testArrangeNN_FullLayoutComplex() {
        // Top: 100x20
        Block top = mock(Block.class);
        when(top.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(100, 20));
        arrangement.add(top, BorderArrangement.TOP);

        // Bottom: 100x20
        Block bottom = mock(Block.class);
        when(bottom.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(100, 20));
        arrangement.add(bottom, BorderArrangement.BOTTOM);

        // Left: 30x100
        Block left = mock(Block.class);
        when(left.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(30, 100));
        arrangement.add(left, BorderArrangement.LEFT);

        // Right: 20x50
        Block right = mock(Block.class);
        when(right.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(20, 50));
        arrangement.add(right, BorderArrangement.RIGHT);

        // Center: 40x80
        Block center = mock(Block.class);
        when(center.arrange(eq(g2), any(RectangleConstraint.class))).thenReturn(new Size2D(40, 80));
        arrangement.add(center, BorderArrangement.CENTER);

        // Calculation Logic Check:
        // h[2] (left) = 100, h[3] (right) = 50. 
        // h[2] = max(100, 50) = 100. h[3] = 100.
        // centerHeight = max(h[2], h[3], h[4]) = max(100, 100, 80) = 100.
        // width = max(w[0], w[1], w[2]+w[4]+w[3]) = max(100, 100, 30+40+20) = max(100, 90) = 100.
        // height = h[0] + h[1] + centerHeight = 20 + 20 + 100 = 140.

        Size2D result = arrangement.callArrangeNN(container, g2);

        assertEquals(100.0, result.width, 1e-9);
        assertEquals(140.0, result.height, 1e-9);

        // Verify Center Bounds
        // w[2] = 30, h[0] = 20, width-w[2]-w[3] = 100-30-20 = 50, centerHeight = 100
        ArgumentCaptor<Rectangle2D.Double> centerCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(center).setBounds(centerCaptor.capture());
        assertEquals(30.0, centerCaptor.getValue().getX(), 1e-9);
        assertEquals(20.0, centerCaptor.getValue().getY(), 1e-9);
        assertEquals(50.0, centerCaptor.getValue().getWidth(), 1e-9);
        assertEquals(100.0, centerCaptor.getValue().getHeight(), 1e-9);

        // Verify Right Bounds
        // width - w[3] = 100 - 20 = 80, h[0] = 20, w[3] = 20, centerHeight = 100
        ArgumentCaptor<Rectangle2D.Double> rightCaptor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(right).setBounds(rightCaptor.capture());
        assertEquals(80.0, rightCaptor.getValue().getX(), 1e-9);
        assertEquals(20.0, rightCaptor.getValue().getY(), 1e-9);
        assertEquals(20.0, rightCaptor.getValue().getWidth(), 1e-9);
        assertEquals(100.0, rightCaptor.getValue().getHeight(), 1e-9);
    }
}
